import jsonschema

from . import exc

_VERSION_CONST = {"const": "2.1"}
_STR_OR_NUM_TYPE = {"type": ["string", "number"]}
_JSONRPC_REQUEST_SCHEMA = {
    "type": "object",
    "properties": {
        "jsonrpc": _VERSION_CONST,
        "id": _STR_OR_NUM_TYPE,
        "sid": _STR_OR_NUM_TYPE,
        "method": {
            "type": "string"
        },
        "params": {}
    },
    "required": ["jsonrpc", "id", "method"],
    "additionalProperties": False
}
_JSONRPC_RESPONSE_SCHEMA = {
    "anyOf": [
        {
            "type": "object",
            "properties": {
                "jsonrpc": _VERSION_CONST,
                "id": _STR_OR_NUM_TYPE,
                "sid": _STR_OR_NUM_TYPE,
                "result": {},
            },
            "required": ["jsonrpc", "id", "result"],
            "additionalProperties": False
        }, {
            "type": "object",
            "properties": {
                "jsonrpc": _VERSION_CONST,
                "id": _STR_OR_NUM_TYPE,
                "sid": _STR_OR_NUM_TYPE,
                "error": {
                    "type": "object",
                    "properties": {
                        "code": {
                            "type": "number"
                        },
                        "message": {
                            "type": "string"
                        },
                        "data": {}
                    },
                    "required": ["code", "message"],
                    "additionalProperties": False,
                }
            },
            "required": ["jsonrpc", "id", "error"],
            "additionalProperties": False
        }
    ]
}
_JSONRPC_NOTIFICATION_SCHEMA = {
    "type": "object",
    "properties": {
        "jsonrpc": _VERSION_CONST,
        "sid": _STR_OR_NUM_TYPE,
        "method": {
            "type": "string"
        },
        "params": {}
    },
    "required": ["jsonrpc", "method"],
    "additionalProperties": False
}


def _validate(data: dict, schema: dict, error_prefix: str):
    try:
        jsonschema.validate(data, schema)
    except jsonschema.ValidationError as e:
        if e.json_path != '$':
            raise exc.MessageValidationError(f'{error_prefix}: {e.message} ({e.json_path})')
        raise exc.MessageValidationError(f'{error_prefix}: {e.message}')


def validate_request(data: dict):
    _validate(data, _JSONRPC_REQUEST_SCHEMA, 'Not a valid JSONRPC request')


def validate_response(data: dict):
    _validate(data, _JSONRPC_RESPONSE_SCHEMA, 'Not a valid JSONRPC response')


def validate_notification(data: dict):
    _validate(data, _JSONRPC_NOTIFICATION_SCHEMA, 'Not a valid JSONRPC notification')
